(function () {
  PyOS.defineApp({
    id: 'voltmetro',
    title: 'Voltmetro ADC (SDK)',
    icon: '⚡',
    width: 340,
    height: 230,
    permissions: ['gpio.read'],
    mount(container, ctx) {
      const { gpio, ui } = ctx.sdk;
      container.innerHTML = `<div class='card' style='display:flex;flex-direction:column;gap:10px;text-align:center;'><select id='vm-pin' class='input mono'></select><div id='vm-val' class='mono' style='font-size:32px;font-weight:700;'>-- mV</div><div id='vm-pct' class='muted mono'>--%</div></div>`;
      const sel = container.querySelector('#vm-pin');
      const elVal = container.querySelector('#vm-val');
      const elPct = container.querySelector('#vm-pct');

      async function init() {
        const info = await gpio.info();
        sel.innerHTML = info.pins.safe_adc.map((p) => `<option value='${p}'>ADC1 GPIO ${p}</option>`).join('');
        poll();
      }
      async function poll() {
        if (!sel.value) return;
        try {
          const r = await gpio.adc(Number(sel.value));
          elVal.textContent = `${r.mv} mV`;
          elPct.textContent = `${r.pct}% (raw ${r.raw_u16})`;
        } catch (e) { ui.toast(e.message, 'err'); }
      }
      sel.onchange = poll;
      init();
      ctx.setInterval(poll, 1000);
    }
  });
})();
